 b=p.chromium.launch(executable_path=shutil.which('chromium'),args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']);c=b.new_context(viewport={'width':1100,'height':850});c.route('https://cdn.jsdelivr.net/npm/three@0.160.1/build/three.module.js',lambda r:r.fulfill(path='/tmp/three.module.js',content_type='text/javascript'));c.route('https://api.github.com/**',lambda r:r.fulfill(json=[]));html=(root/'index.html').read_text().replace('let previous=performance.now();',hook).replace('cam.position.lerp(target,','if(!window.__freeze)cam.position.lerp(target,').replace('else cam.lookAt(player.position.x,player.position.y+1.1,player.position.z);','else if(!window.__freeze)cam.lookAt(player.position.x,player.position.y+1.1,player.position.z);');c.route(base,lambda r:r.fulfill(body=html,content_type='text/html'));page=c.new_page();errors=[];page.on('pageerror',lambda e:(errors.append(str(e)),print('ERROR',str(e),flush=True)));page.on('console',lambda m:errors.append(m.text)if m.type=='error'and'Shader Error'in m.text else None);page.goto(base);page.wait_for_function('window.__gaussTest',timeout=180000);page.get_by_role('button',name='開始探索',exact=True).click();result=page.evaluate('window.__gaussTest.test()');print(json.dumps(result),flush=True)
